import{_ as e,o as a,c as i,a2 as s}from"./chunks/framework.Dxeykp0S.js";const k=JSON.parse('{"title":"Day 2 · 四大数据结构：list / tuple / dict / set","description":"","frontmatter":{},"headers":[],"relativePath":"novice/02-data-structures.md","filePath":"novice/02-data-structures.md","lastUpdated":1787141678000}'),d={name:"novice/02-data-structures.md"};function o(r,t,l,n,c,h){return a(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="day-2-·-四大数据结构-list-tuple-dict-set" tabindex="-1">Day 2 · 四大数据结构：list / tuple / dict / set <a class="header-anchor" href="#day-2-·-四大数据结构-list-tuple-dict-set" aria-label="Permalink to &quot;Day 2 · 四大数据结构：list / tuple / dict / set&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>Python 有四种核心容器类型： list、tuple、dict、set。什么时候用哪个、它们各自有什么性能特征，是写出地道 Python 的关键。今天的高潮是<strong>推导式（comprehension）</strong>——学会它，你会开始嫌弃 <code>for</code> 循环。</p><h2 id="课程目标" tabindex="-1">课程目标 <a class="header-anchor" href="#课程目标" aria-label="Permalink to &quot;课程目标&quot;">​</a></h2><ul><li>掌握四种内置数据结构的 API 与适用场景</li><li>理解可变（list/dict/set）与不可变（tuple/str）的区别及影响</li><li>熟练使用列表/字典/集合推导式</li><li>掌握解包（unpacking）与 <code>*</code> / <code>**</code> 的用法</li></ul><h2 id="阅读学习" tabindex="-1">阅读学习 <a class="header-anchor" href="#阅读学习" aria-label="Permalink to &quot;阅读学习&quot;">​</a></h2><ul><li><a href="https://docs.python.org/zh-cn/3/tutorial/datastructures.html" target="_blank" rel="noreferrer">Python 官方教程第 5 章：数据结构</a></li><li>对照速览：</li></ul><table tabindex="0"><thead><tr><th>JS</th><th>Python</th><th>说明</th></tr></thead><tbody><tr><td><code>arr.map(f)</code></td><td><code>[f(x) for x in arr]</code></td><td>推导式优先于 <code>map()</code></td></tr><tr><td><code>arr.filter(f)</code></td><td><code>[x for x in arr if f(x)]</code></td><td>同上</td></tr><tr><td><code>Object.entries(obj)</code></td><td><code>obj.items()</code></td><td>dict 遍历</td></tr><tr><td><code>{...a, ...b}</code></td><td><code>{**a, **b}</code> 或 <code>a | b</code>（3.9+）</td><td>合并 dict</td></tr><tr><td><code>[...arr]</code></td><td><code>[*arr]</code> 或 <code>arr.copy()</code></td><td>浅拷贝</td></tr><tr><td>解构 <code>const {a, b} = obj</code></td><td><code>a, b = pair</code>（序列解包）</td><td>dict 没有同名解构语法</td></tr><tr><td><code>new Set()</code></td><td><code>set()</code> 或 <code>{1, 2, 3}</code></td><td>注意 <code>{}</code> 是空 dict 不是空 set！</td></tr></tbody></table><h2 id="任务作业" tabindex="-1">任务作业 <a class="header-anchor" href="#任务作业" aria-label="Permalink to &quot;任务作业&quot;">​</a></h2><ol><li><p><strong>数据处理管道</strong>：给定一个包含 dict 的列表（模拟 API 返回的用户数据，含 name/age/city 字段），用<strong>嵌套推导式</strong>完成：筛选年龄 ≥ 18 的用户 → 按城市分组 → 输出每个城市的用户名列表。全程禁止写显式 <code>for</code> 循环。</p></li><li><p><strong>词频统计器</strong>：实现 <code>word_count(text: str) -&gt; list[tuple[str, int]]</code>，统计英文文本词频并按频率降序返回前 10 名。要求：先用字典手写一遍，再查标准库找到&quot;作弊&quot;方案（提示：<code>collections.Counter</code>），对比两者。</p></li><li><p><strong>tuple 的尊严</strong>：解释并实现——为什么函数多返回值用 tuple？写一个 <code>min_max_avg(nums)</code> 返回三元组，并用解包接收。再实现函数参数解包：<code>distance(*point)</code> 接受 <code>distance(3, 4)</code> 和 <code>distance(*(3, 4))</code> 两种调用。</p></li><li><p><strong>浅拷贝陷阱</strong>：</p></li></ol><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">matrix </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">matrix[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(matrix)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 输出什么？为什么？</span></span></code></pre></div><p>写出三种正确的初始化 3x3 矩阵的方式。</p><ol start="5"><li><strong>set 实战</strong>：给你两个列表（各 3000 个随机整数），分别用&quot;双重循环&quot;和&quot;set 交集&quot;求共同元素，用 <code>time</code> 模块计时对比，感受 O(n²) vs O(n) 的差距。然后把数据量加到 10 万再跑一次 set 版本（双重循环版本就别跑了，O(n²) 在 Python 里要跑到天荒地老——这正是本实验的结论）。</li></ol><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><ul><li>为什么 tuple 可以作为 dict 的 key 而 list 不行？（哈希与不可变性）</li><li><code>dict</code> 在 Python 3.7+ 中保证什么顺序？</li><li><code>{}</code> 创建的是什么？空集合怎么创建？</li><li>推导式和生成器表达式 <code>(x for x in arr)</code> 有什么区别？处理 1GB 文件时该用哪个？</li><li>列表的 <code>+=</code> 和 <code>.extend()</code> 完全一样吗？（进阶：对元组用 <code>+=</code> 会发生什么？）</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>记录今天的学习笔记。</p><h2 id="拓展阅读" tabindex="-1">拓展阅读 <a class="header-anchor" href="#拓展阅读" aria-label="Permalink to &quot;拓展阅读&quot;">​</a></h2><ul><li><a href="https://docs.python.org/zh-cn/3/library/collections.html" target="_blank" rel="noreferrer">collections 模块官方文档</a> —— Counter、defaultdict、deque、namedtuple，个个都是神器</li><li><a href="https://wiki.python.org/moin/TimeComplexity" target="_blank" rel="noreferrer">Python 数据结构的时间复杂度</a></li></ul><h2 id="预告" tabindex="-1">预告 <a class="header-anchor" href="#预告" aria-label="Permalink to &quot;预告&quot;">​</a></h2><p>下一节学习<a href="./03-functions">函数</a>：继续掌握 <code>*args</code>、<code>**kwargs</code> 与 keyword-only 等 Python 参数机制。</p>`,21)])])}const u=e(d,[["render",o]]);export{k as __pageData,u as default};
